void ILI9341_Draw_PartImage(const uint16_t* image, uint16_t x, uint16_t y, uint16_t w, uint16_t h)
{
    ILI9341_Set_Address(x, y, x + w - 1, y + h - 1);

    ILI9341_Write_Command(0x2C);
    for (uint32_t i = 0; i < w * h; i++)
    {
        ILI9341_Write_Data(image[i] >> 8);
        ILI9341_Write_Data(image[i] & 0xFF);
    }
}
uint16_t CRC16_2(uint8_t *ptr, uint8_t length)
{
	uint16_t crc = 0xFFFF;
	uint8_t s = 0x00;
	while(length--){
		crc ^= *ptr++;
		for(s = 0; s < 8;s++)
		{
			if((crc & 0x01) != 0){
				crc >>= 1;
				crc ^= 0xA001;
			}else crc >>= 1;
		}
	}
	return crc;
}
uint16_t RGB565(uint8_t r, uint8_t g, uint8_t b) {
    return ((r & 0xF8) << 8) |
           ((g & 0xFC) << 3) |
           (b >> 3);
}
uint16_t LightenColor(uint16_t color, uint8_t percent)
{
    if (percent > 100) percent = 100;

    uint8_t r = (color >> 11) & 0x1F;
    uint8_t g = (color >> 5)  & 0x3F;
    uint8_t b =  color        & 0x1F;

    uint8_t rMax = 31;
    uint8_t gMax = 63;
    uint8_t bMax = 31;

    r = r + ((rMax - r) * percent) / 100;
    g = g + ((gMax - g) * percent) / 100;
    b = b + ((bMax - b) * percent) / 100;

    return (r << 11) | (g << 5) | b;
}
void ShowColor(uint16_t color, uint8_t percent, uint16_t position_y)
{
    ILI9341_Draw_Filled_Circle(20, position_y, 15, color);
    ILI9341_Draw_Rectangle(60, position_y - 10, 120, 20, LightenColor(color, 50));
    uint16_t filledWidth = (120 * percent) / 100;
    ILI9341_Draw_Rectangle(60, position_y - 10, filledWidth, 20, color);
    char buf[10];
    sprintf(buf, "%d %%", percent);
    ILI9341_Draw_Text(buf, 200, position_y, BLACK, 2, WHITE);
}
void ShowTemperture()
{
	char temp[10];
		sprintf(temp, "%4.1f C", t);
		ILI9341_Draw_Text(temp, 20, 20, BLACK, 2, WHITE);
		ILI9341_Draw_Filled_Circle(130, 30, 15, RGB565(red, green, blue));
		char humid[10];
		sprintf(humid, "%4.1f %%RH", h);
		ILI9341_Draw_Text(humid, 170, 20, BLACK, 2, WHITE);
}
void DisplayMenu()
{
	ILI9341_Fill_Screen(WHITE);
	ILI9341_Set_Rotation(SCREEN_HORIZONTAL_1);
	ShowTemperture();
	ShowColor(RED, red_percent, 80);
	ShowColor(GREEN, green_percent, 140);
	ShowColor(BLUE, blue_percent, 200);
}
void UpdateColor(uint8_t *color, uint8_t *percent)
{
    *percent = (*percent + 10) % 110;
    *color = (uint8_t)((*percent * 255) / 100);
    DisplayMenu();
}
void DisplayProfile(const uint16_t* image, const char *fn, const char *ln, int number)
{
    ILI9341_Fill_Screen(WHITE);
    ILI9341_Set_Rotation(SCREEN_HORIZONTAL_1);
    ILI9341_Draw_PartImage(image, 20, 60, 80, 100);
    static char firstname[20];
    sprintf(firstname, "%s", fn);
    static char lastname[20];
    sprintf(lastname, "%s", ln);
    static char studentId[10];
    sprintf(studentId, "%d", number);
    ILI9341_Draw_Text("GROUP NO.6", 120, 50, RGB565(red, green, blue), 2, WHITE);
    ILI9341_Draw_Text(firstname, 120, 100, RGB565(red, green, blue), 2, WHITE);
    ILI9341_Draw_Text(lastname, 120, 150, RGB565(red, green, blue), 2, WHITE);
    ILI9341_Draw_Text(studentId, 120, 200, RGB565(red, green, blue), 2, WHITE);
}
